-- M03 identity
CREATE TABLE users(id VARCHAR(36) PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(80) NOT NULL, role VARCHAR(16) NOT NULL);
-- M04 product; M02 changes sale state only through ProductPort
CREATE TABLE products(id VARCHAR(36) PRIMARY KEY, seller_id VARCHAR(36) NOT NULL, title VARCHAR(120) NOT NULL, description TEXT NOT NULL, category VARCHAR(40) NOT NULL, price BIGINT NOT NULL, images JSON NOT NULL, audit_status VARCHAR(20) NOT NULL, sale_status VARCHAR(20) NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, CONSTRAINT fk_product_seller FOREIGN KEY(seller_id) REFERENCES users(id), CHECK(price>0));
-- M02 transaction and simulated money
CREATE TABLE accounts(user_id VARCHAR(36) PRIMARY KEY, balance BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id), CHECK(balance>=0));
CREATE TABLE orders(id VARCHAR(36) PRIMARY KEY, product_id VARCHAR(36) NOT NULL, buyer_id VARCHAR(36) NOT NULL, seller_id VARCHAR(36) NOT NULL, amount BIGINT NOT NULL, status VARCHAR(32) NOT NULL, close_reason VARCHAR(40), created_at BIGINT NOT NULL, pay_deadline BIGINT NOT NULL, receipt_deadline BIGINT, receipt_remaining BIGINT, receipt_paused BOOLEAN NOT NULL DEFAULT FALSE, shipping_blocked BOOLEAN NOT NULL DEFAULT FALSE, settlement_blocked BOOLEAN NOT NULL DEFAULT FALSE, payment_generation BIGINT NOT NULL DEFAULT 0, receipt_generation BIGINT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(buyer_id) REFERENCES users(id), FOREIGN KEY(seller_id) REFERENCES users(id), CHECK(amount>0), INDEX idx_orders_buyer(buyer_id), INDEX idx_orders_seller(seller_id));
CREATE TABLE product_holds(product_id VARCHAR(36) PRIMARY KEY, order_id VARCHAR(36) NOT NULL UNIQUE, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE escrows(order_id VARCHAR(36) PRIMARY KEY, amount BIGINT NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE money_operations(id VARCHAR(36) PRIMARY KEY, order_id VARCHAR(36) NOT NULL, kind VARCHAR(20) NOT NULL, amount BIGINT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(order_id,kind), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE money_entries(operation_id VARCHAR(36) NOT NULL, account_id VARCHAR(40) NOT NULL, amount BIGINT NOT NULL, PRIMARY KEY(operation_id,account_id), FOREIGN KEY(operation_id) REFERENCES money_operations(id));
CREATE TABLE shipments(id VARCHAR(36) PRIMARY KEY, order_id VARCHAR(36) NOT NULL, direction VARCHAR(12) NOT NULL, tracking_number VARCHAR(100) NOT NULL, evidence JSON NOT NULL, status VARCHAR(20) NOT NULL, shipped_at BIGINT NOT NULL, due_at BIGINT NOT NULL, delivered_at BIGINT, generation BIGINT NOT NULL DEFAULT 0, UNIQUE(order_id,direction), FOREIGN KEY(order_id) REFERENCES orders(id));
-- M07 case and decision source
CREATE TABLE cases(id VARCHAR(36) PRIMARY KEY, order_id VARCHAR(36) NOT NULL, buyer_id VARCHAR(36) NOT NULL, kind VARCHAR(20) NOT NULL, reason TEXT NOT NULL, status VARCHAR(32) NOT NULL, decision VARCHAR(32), decision_reason TEXT, deadline BIGINT, generation BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(order_id) REFERENCES orders(id), INDEX idx_cases_order(order_id));
CREATE TABLE case_decisions(id VARCHAR(36) PRIMARY KEY, case_id VARCHAR(36) NOT NULL, actor_id VARCHAR(36) NOT NULL, action VARCHAR(32) NOT NULL, reason TEXT NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(case_id) REFERENCES cases(id));
CREATE TABLE applied_decisions(decision_id VARCHAR(36) PRIMARY KEY, order_id VARCHAR(36) NOT NULL, FOREIGN KEY(decision_id) REFERENCES case_decisions(id));
-- M06 moderation demo state
CREATE TABLE reports(id VARCHAR(36) PRIMARY KEY, product_id VARCHAR(36) NOT NULL, reporter_id VARCHAR(36) NOT NULL, reason TEXT NOT NULL, status VARCHAR(20) NOT NULL, result TEXT, created_at BIGINT NOT NULL);
CREATE TABLE moderation_reviews(id VARCHAR(36) PRIMARY KEY, product_id VARCHAR(36) NOT NULL, actor_id VARCHAR(36) NOT NULL, decision VARCHAR(20) NOT NULL, reason TEXT NOT NULL, created_at BIGINT NOT NULL);
-- M08 clock, tasks, committed events
CREATE TABLE clock_state(id INT PRIMARY KEY, offset_millis BIGINT NOT NULL, frozen_at BIGINT);
INSERT INTO clock_state VALUES(1,0,NULL);
CREATE TABLE deadlines(id BIGINT AUTO_INCREMENT PRIMARY KEY, aggregate_id VARCHAR(36) NOT NULL, kind VARCHAR(32) NOT NULL, generation BIGINT NOT NULL, due_at BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', UNIQUE(aggregate_id,kind,generation), INDEX idx_due(status,due_at));
CREATE TABLE outbox(id BIGINT AUTO_INCREMENT PRIMARY KEY, recipient_id VARCHAR(36) NOT NULL, aggregate_id VARCHAR(36) NOT NULL, event_type VARCHAR(40) NOT NULL, message VARCHAR(255) NOT NULL, created_at BIGINT NOT NULL, delivered BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE notifications(id BIGINT PRIMARY KEY, recipient_id VARCHAR(36) NOT NULL, aggregate_id VARCHAR(36) NOT NULL, message VARCHAR(255) NOT NULL, created_at BIGINT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, INDEX idx_recipient(recipient_id));
-- shared infrastructure. Requests are stored atomically with business result.
CREATE TABLE request_results(actor_id VARCHAR(36) NOT NULL, operation VARCHAR(80) NOT NULL, request_key VARCHAR(100) NOT NULL, parameter_hash VARCHAR(64) NOT NULL, result_json JSON, PRIMARY KEY(actor_id,operation,request_key));
CREATE TABLE audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, action VARCHAR(80) NOT NULL, aggregate_id VARCHAR(36), created_at BIGINT NOT NULL);
CREATE TABLE files(id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL, purpose VARCHAR(30) NOT NULL, mime VARCHAR(40) NOT NULL, filename VARCHAR(255) NOT NULL, storage_name VARCHAR(64) NOT NULL, byte_size BIGINT NOT NULL, linked_type VARCHAR(20), linked_id VARCHAR(36), created_at BIGINT NOT NULL);
